import{z as s,x as l,o as B,c as C,q as r,j as i,D as e,d as A,s as o,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"协议实现的陷阱","description":"","frontmatter":{"title":"协议实现的陷阱","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-protocol-pitfalls.md","filePath":"cs/ce-protocol-pitfalls.md","lastUpdated":1791063341000}'),F={name:"cs/ce-protocol-pitfalls.md"};function c(d,E,h,D,p,m){const n=l("Mermaid");return B(),C("div",null,[E[2]||(E[2]=r('<h1 id="协议实现的陷阱" tabindex="-1">协议实现的陷阱 <a class="header-anchor" href="#协议实现的陷阱" aria-label="Permalink to &quot;协议实现的陷阱&quot;">​</a></h1><div class="epigraph"><p>原语各自正确，组合起来才出事：预言机不在算法里，在错误码、时序与「顺手回一句为什么失败」里。</p><footer>—— 据 Bleichenbacher, 1998；Vaudenay, 2002；Ferguson, Schneier and Kohno, *Cryptography Engineering* 整理</footer></div><p><a href="/cs/ce-kem-hybrid">上一课</a>把 KEM+DEM 的组合合同钉住。本课面对工程里更常见的实况：协议不是原语的加法，历史上大部分破绽发生在组合处——错误消息区分了填充错误与 MAC 错误，时序区分了分支，协商字段放行了降级。主干<a href="/cs/padding-oracle">填充预言机</a>已给过 CBC 那口井；<a href="/cs/tls-handshake">TLS 握手</a>给了 Finished 绑定握手字节的机制。缺口是把案例收成一份「组合纪律」清单：任何自写协议过一遍都该被这张表拷问。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合失败的共同形状：协议向攻击者开放一个<strong>判定预言</strong>。Bleichenbacher 1998 打 PKCS#1 v1.5 的 RSA 解密：服务器对「填充错」与「格式对但后续错」返回不同错误，攻击者据此把密文盲化、逐字节逼近，约一百万次查询内解出明文；二十多年后这个预言仍在多家产品里复活（ROBOT）。CBC 侧同型：填充校验先于 MAC 校验、错误码不同即预言机（Vaudenay 2002）。Lucky 13 证明连「错误码统一」都不够：MAC 校验的处理量随填充长度变化，预言从错误码挪进了纳秒级时序。缺口不是背案例，而是识别预言的四类来源：错误码、时序、可见的状态变化、可重放性。<span class="marginnote">「判定预言」可以类比成猜数字游戏里每猜一次都告诉你「大了还是小了」：单独一句回答无害，反复问就能把秘密逼出来。协议里「填充错」与「MAC 错」返回不同错误，等于把这样的提示白送给攻击者——Bleichenbacher 攻击正是靠约一百万次「大了/小了」式的提问解出明文。</span></p><h3 id="降级与协商" tabindex="-1">降级与协商 <a class="header-anchor" href="#降级与协商" aria-label="Permalink to &quot;降级与协商&quot;">​</a></h3><p>协商字段本身是攻击面。客户端与服务器各自报版本与套件，中间人删掉高版本与强套件——FREAK、Logjam 都靠复活出口级弱算法得手。RFC 5746 之后，TLS 用 Finished 把全部握手字节哈希进密钥材料：篡改过协商的中间人，造不出与两端一致的 Finished。把这条机制通用化就是本课的核心纪律：<strong>把协商过程本身绑进认证</strong>，而不是信任每个字段的独立正确性。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>组合纪律五条。其一，失败一律不可区分：解密失败的对外表现只有一种（连接终止或通用错误），内部区分只进日志，且日志路径不带时序差。其二，认证次序用 Encrypt-then-MAC 形状或直接 AEAD；「MAC-then-encrypt」的正确性靠「MAC 校验时间与内容无关」来补——这是 Lucky 13 用多年补丁换来的教训，不该再付一次。其三，防重放要有显式合同：nonce、计数器或时间戳，且落进认证范围；「消息里有时间戳」本身不防重放，除非时间戳被 MAC 覆盖。<span class="marginnote">常见误区：以为消息里带了时间戳就自动防重放。实际重放时攻击者把整条消息原样搬过来，时间戳也原样到场，逐字段校验全过。只有把时间戳（或 nonce、计数器）盖进 MAC/AEAD 的认证范围，重放的那份才会因标签对不上或计数器越界被拒。</span>其四，常量时间比较标签与 MAC——<a href="/cs/length-extension-hmac">长度扩展与 HMAC</a>的小结已点名；任何 <code>==</code> 比较密钥材料都重新开口预言。其五，不自写协议：组合问题连专业团队都反复失手（renegotiation 2009、Bleichenbacher 两度复活），应用层该做的是选 TLS、Noise 这类经过战役的框架，把自创减到最少。</p>',9)),(B(),i(t,null,{default:e(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E8%A7%A3%E5%AF%86%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20Q%7B%22%E5%AF%B9%E5%A4%96%E5%A6%82%E4%BD%95%E5%9B%9E%E7%AD%94%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%8C%BA%E5%88%86%E5%A1%AB%E5%85%85%20%2F%20MAC%20%2F%20%E6%A0%BC%E5%BC%8F%7C%20ORAC%5B%22%E9%94%99%E8%AF%AF%E7%A0%81%E9%A2%84%E8%A8%80%E6%9C%BA%22%5D%0A%20%20ORAC%20--%3E%20BAD%5B%22Bleichenbacher%20%2F%20POODLE%20%E5%9E%8B%E6%94%BB%E5%87%BB%22%5D%0A%20%20Q%20--%3E%7C%E7%BB%9F%E4%B8%80%E9%94%99%E8%AF%AF%E4%BD%86%E6%97%B6%E5%BA%8F%E4%B8%8D%E5%90%8C%7C%20T13%5B%22%E6%97%B6%E5%BA%8F%E9%A2%84%E8%A8%80%E6%9C%BA%EF%BC%88Lucky%2013%20%E5%9E%8B%EF%BC%89%22%5D%0A%20%20T13%20--%3E%20BAD%0A%20%20Q%20--%3E%7C%E7%BB%9F%E4%B8%80%E4%B8%94%E5%B8%B8%E9%87%8F%E6%97%B6%E9%97%B4%7C%20OK%5B%22%E9%A2%84%E8%A8%80%E5%85%B3%E9%97%AD%22%5D%0A%20%20NEG%5B%22%E5%8D%8F%E5%95%86%E8%A2%AB%E4%B8%AD%E9%97%B4%E4%BA%BA%E6%94%B9%E5%86%99%22%5D%20--%3E%20FIN%7B%22Finished%20%E7%BB%91%E5%AE%9A%E6%8F%A1%E6%89%8B%E5%AD%97%E8%8A%82%3F%22%7D%0A%20%20FIN%20--%3E%7C%E5%90%A6%7C%20DG%5B%22%E9%99%8D%E7%BA%A7%EF%BC%9AFREAK%20%2F%20Logjam%20%E5%9E%8B%22%5D%0A%20%20FIN%20--%3E%7C%E6%98%AF%7C%20SAFE%5B%22%E5%8D%8F%E5%95%86%E8%A2%AB%E8%AE%A4%E8%AF%81%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("为什么预言机挡不住？因为组合层的安全目标与原语层不同：原语按「挑战不可区分」证明，协议要按「任何判定结果不依赖秘密」重证一遍。错误路径上每一处提前返回，都在游戏之外多了一个可观测输出。TLS 1.3 把这条纪律制度化：记录层统一 AEAD、失败即连接终止、握手转录进 Finished、降级用哨兵值标记（服务器拒绝旧版本连接时写死一个特定随机串供客户端识别）。"),a("span",{class:"marginnote"},"哨兵值是个小巧的应用：被迫降级的一端把握手随机数的固定几个字节写成约定值，支持更高版本的对端一见便知「这是被迫降级，不是真实随机」，于是拒绝连接。攻击者伪造不了它，因为随机数在 Finished 的认证范围内。"),A("对照读，"),a("a",{href:"/cs/ce-aead-deep"},"AEAD 的深入"),A("的「标签失败整体丢弃」正是这条纪律在记录层的落地：合同在原语层写好了，协议层的职责只是不去重新打开它。")],-1)),(B(),i(t,null,{default:e(()=>[o(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUDIT%5B%22%E8%87%AA%E5%86%99%E5%8D%8F%E8%AE%AE%E9%80%90%E6%9D%A1%E6%8B%B7%E9%97%AE%22%5D%20--%3E%20A%7B%22%E5%A4%B1%E8%B4%A5%E5%AF%B9%E5%A4%96%E5%8F%AA%E6%9C%89%E4%B8%80%E7%A7%8D%E6%A0%B7%E5%AD%90%E5%90%97%EF%BC%9F%22%7D%0A%20%20A%20--%3E%7C%22%E5%90%A6%22%7C%20H1%5B%22%E5%A0%B5%EF%BC%9A%E7%BB%9F%E4%B8%80%E9%94%99%E8%AF%AF%EF%BC%8C%E5%8C%BA%E5%88%86%E5%8F%AA%E8%BF%9B%E6%97%A5%E5%BF%97%22%5D%0A%20%20A%20--%3E%7C%22%E6%98%AF%22%7C%20B%7B%22%E6%A0%A1%E9%AA%8C%E8%80%97%E6%97%B6%E4%B8%8E%E5%86%85%E5%AE%B9%E6%97%A0%E5%85%B3%E5%90%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20H2%5B%22%E5%A0%B5%EF%BC%9A%E5%B8%B8%E9%87%8F%E6%97%B6%E9%97%B4%E6%AF%94%E8%BE%83%E4%B8%8E%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%7B%22%E9%98%B2%E9%87%8D%E6%94%BE%E5%AD%97%E6%AE%B5%E8%BF%9B%E8%AE%A4%E8%AF%81%E8%8C%83%E5%9B%B4%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20H3%5B%22%E5%A0%B5%EF%BC%9Anonce%20%E6%88%96%E8%AE%A1%E6%95%B0%E5%99%A8%E7%BA%B3%E5%85%A5%E8%AE%A4%E8%AF%81%22%5D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20D%7B%22%E5%8D%8F%E5%95%86%E5%AD%97%E8%8A%82%E7%BB%91%E8%BF%9B%E8%AE%A4%E8%AF%81%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20H4%5B%22%E5%A0%B5%EF%BC%9A%E6%8F%A1%E6%89%8B%E8%BD%AC%E5%BD%95%E5%93%88%E5%B8%8C%E8%BF%9B%20Finished%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20PASS%5B%22%E5%9B%9B%E9%97%AE%E5%85%A8%E8%BF%87%EF%BC%8C%E5%86%8D%E8%AF%84%E4%BC%B0%E6%98%AF%E5%90%A6%E5%8F%AF%E5%85%8D%E8%87%AA%E5%86%99%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">Lucky 13 的修补成本常被低估：统一错误码之后，实现还要把 HMAC 校验做成「无论填充对错都执行相同指令数」，并在缓存与循环里抹掉时间差。TLS 1.3 直接删掉 CBC 套件——用「少一个模式」换「少一类预言」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>时序如何在纳秒尺度被测量、常量时间代码怎么写、编译器如何重新引入分支，是下一课「侧信道」的主题。本课不重述 CBC 填充预言的代数细节（见<a href="/cs/padding-oracle">填充预言机</a>），也不展开证书链校验的陷阱（判名规则不在协议组合层）。随机数短缺引发的协议失败（重复的 \\(k\\)、可预测的 nonce）按「随机数」课的口径处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合层破绽的共同形状是判定预言：错误码、时序、状态变化、可重放性。</li><li>失败对外一律不可区分且常量时间；MAC-then-encrypt 的时序债是 Lucky 13 的教训。</li><li>协商要被认证：Finished 绑定握手字节；字段独立正确不等于组合正确。</li><li>防重放要显式合同且进认证范围；自写协议默认有预言，选经过战役的框架。</li><li>出处：Bleichenbacher, 1998；Vaudenay, 2002；RFC 5746；RFC 8446；Ferguson, Schneier and Kohno。</li></ul>',5))])}const _=s(F,[["render",c]]);export{f as __pageData,_ as default};
